mkitem!{mkstruct!{# [doc = " A TCP stream between a local and a remote socket."] # [doc = ""] # [doc = " After creating a `TcpStream` by either [`connect`]ing to a remote host or"] # [doc = " [`accept`]ing a connection on a [`TcpListener`], data can be transmitted"] # [doc = " by [reading] and [writing] to it."] # [doc = ""] # [doc = " The connection will be closed when the value is dropped. The reading and writing"] # [doc = " portions of the connection can also be shut down individually with the [`shutdown`]"] # [doc = " method."] # [doc = ""] # [doc = " The Transmission Control Protocol is specified in [IETF RFC 793]."] # [doc = ""] # [doc = " [`accept`]: TcpListener::accept"] # [doc = " [`connect`]: TcpStream::connect"] # [doc = " [IETF RFC 793]: https://tools.ietf.org/html/rfc793"] # [doc = " [reading]: Read"] # [doc = " [`shutdown`]: TcpStream::shutdown"] # [doc = " [writing]: Write"] # [doc = ""] # [doc = " # Examples"] # [doc = ""] # [doc = " ```no_run"] # [doc = " use std::io::prelude::*;"] # [doc = " use std::net::TcpStream;"] # [doc = ""] # [doc = " fn main() -> std::io::Result<()> {"] # [doc = "     let mut stream = TcpStream::connect(\"127.0.0.1:34254\")?;"] # [doc = ""] # [doc = "     stream.write(&[1])?;"] # [doc = "     stream.read(&mut [0; 128])?;"] # [doc = "     Ok(())"] # [doc = " } // the stream is closed here"] # [doc = " ```"] # [doc = ""] # [doc = " # Platform-specific Behavior"] # [doc = ""] # [doc = " On Unix, writes to the underlying socket in `SOCK_STREAM` mode are made with"] # [doc = " `MSG_NOSIGNAL` flag. This suppresses the emission of the  `SIGPIPE` signal when writing"] # [doc = " to disconnected socket. In some cases, getting a `SIGPIPE` would trigger process termination."] # [stable (feature = "rust1" , since = "1.0.0")] pub struct TcpStream (net_imp :: TcpStream) ;}}
